(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const ui = {
    playerHealth: document.getElementById('playerHealth'), enemyHealth: document.getElementById('enemyHealth'),
    playerMeter: document.getElementById('playerMeter'), enemyMeter: document.getElementById('enemyMeter'),
    timer: document.getElementById('timer'), banner: document.getElementById('banner'), title: document.getElementById('bannerTitle'),
    sub: document.getElementById('bannerSub'), flash: document.getElementById('hitFlash'), toast: document.getElementById('comboToast'),
    status: document.getElementById('fightStatus'), pWins: document.getElementById('pWins'), eWins: document.getElementById('eWins')
  };
  const keys = new Set();
  const palette = {player:{cloth:[221,62,38],dark:[25,21,28],accent:[247,151,73]},enemy:{cloth:[40,159,193],dark:[20,28,40],accent:[119,220,232]}};
  const attacks = {hp:{damage:7,range:105,kind:'punch',height:0,stun:20},lp:{damage:5,range:91,kind:'punch',height:1,stun:16},hk:{damage:10,range:127,kind:'kick',height:0,stun:27},lk:{damage:7,range:105,kind:'kick',height:1,stun:21}};
  const state = {playing:false,roundOver:false,time:99,last:0,elapsed:0,shake:0,projectiles:[],particles:[],sequence:[],combo:0,comboUntil:0,screenFlash:0,round:1};
  const makeFighter=(x,facing,isPlayer)=>({x,y:0,facing,isPlayer,health:100,meter:22,anim:'idle',animTime:0,stun:0,attackCooldown:0,block:false,crouch:false,run:false,jump:0,airVy:0,flash:0,aiWait:50,aiMode:'approach',wins:0,freeze:0});
  const player=makeFighter(275,1,true), enemy=makeFighter(685,-1,false);

  // One compact, shared seven-pose atlas. Fighter colors are palette-swapped from the same pixels.
  const atlas=document.createElement('canvas'); atlas.width=7*80; atlas.height=112;
  const ac=atlas.getContext('2d');
  const poses=['idle','hp','lp','hk','lk','block','hit'];
  function spritePose(g,x,pose){
    const cx=x+40, ground=99; g.save(); g.translate(cx,ground);
    const cloth='#dd3e26', dark='#19151c', accent='#f79749', skin='#bd8565';
    g.lineCap='square';g.lineJoin='round';
    const crouch=pose==='lp'||pose==='lk', attack=pose==='hp'||pose==='lp'||pose==='hk'||pose==='lk';
    const hit=pose==='hit', blocking=pose==='block';
    // trailing leg and boots
    g.strokeStyle=dark;g.lineWidth=10;g.beginPath();g.moveTo(-5,-28);g.lineTo(crouch? -19:-16,-9);g.lineTo(crouch?-25:-20,-5);g.stroke();
    g.fillStyle=accent;g.fillRect(crouch?-29:-24,-8,17,6);
    g.strokeStyle=dark;g.lineWidth=10;g.beginPath();g.moveTo(5,-28);g.lineTo(crouch?16:18,-10);g.lineTo(crouch?21:24,-5);g.stroke();
    g.fillStyle=accent;g.fillRect(crouch?16:19,-8,17,6);
    // torso, sash and belt
    g.fillStyle=dark;g.beginPath();g.moveTo(-14,-72);g.lineTo(13,-72);g.lineTo(16,-30);g.lineTo(-14,-30);g.closePath();g.fill();
    g.fillStyle=cloth;g.beginPath();g.moveTo(-11,-75);g.lineTo(12,-75);g.lineTo(13,-34);g.lineTo(-13,-34);g.closePath();g.fill();
    g.fillStyle=accent;g.fillRect(-14,-38,29,5);g.fillRect(-1,-35,4,11);
    // head and wrapped hood
    g.fillStyle=skin;g.fillRect(-9,-94,19,21);g.fillStyle=dark;g.fillRect(-12,-99,24,16);g.fillRect(-14,-91,28,7);
    g.fillStyle=cloth;g.fillRect(-11,-90,23,5);g.fillStyle='#efe6d9';g.fillRect(2,-88,7,2);
    g.fillStyle=dark;g.fillRect(-12,-103,24,6);g.fillRect(-10,-100,4,4);
    // scarf tail
    g.fillStyle=cloth;g.beginPath();g.moveTo(-9,-78);g.lineTo(-23,-70);g.lineTo(-8,-72);g.closePath();g.fill();
    // arms, posed per action
    g.strokeStyle=dark;g.lineWidth=9;
    if(pose==='hp'){g.beginPath();g.moveTo(10,-68);g.lineTo(27,-60);g.lineTo(47,-59);g.stroke();g.fillStyle=skin;g.fillRect(41,-64,12,10)}
    else if(pose==='lp'){g.beginPath();g.moveTo(8,-59);g.lineTo(28,-49);g.lineTo(42,-48);g.stroke();g.fillStyle=skin;g.fillRect(37,-53,12,10)}
    else if(pose==='hk'||pose==='lk'){g.beginPath();g.moveTo(10,-67);g.lineTo(18,-51);g.stroke();g.fillStyle=skin;g.fillRect(12,-55,11,9)}
    else if(blocking){g.beginPath();g.moveTo(10,-68);g.lineTo(20,-83);g.lineTo(5,-88);g.stroke();g.fillStyle=skin;g.fillRect(0,-94,12,10);g.beginPath();g.moveTo(-10,-65);g.lineTo(-22,-55);g.stroke()}
    else if(hit){g.beginPath();g.moveTo(8,-68);g.lineTo(-3,-56);g.stroke();g.beginPath();g.moveTo(-10,-66);g.lineTo(-20,-56);g.stroke()}
    else{g.beginPath();g.moveTo(10,-68);g.lineTo(20,-53);g.stroke();g.fillStyle=skin;g.fillRect(16,-57,11,9);g.beginPath();g.moveTo(-10,-66);g.lineTo(-20,-54);g.stroke();g.fillStyle=skin;g.fillRect(-26,-59,11,9)}
    // distinctive little wrist wraps
    if(attack){g.fillStyle=accent;g.fillRect(pose==='hp'?37:pose==='lp'?34:8,pose==='hp'?-64:pose==='lp'?-53:-54,7,4)}
    g.restore();
  }
  poses.forEach((p,i)=>spritePose(ac,i*80,p));
  const fighterSheets={};
  for(const [name,pal] of Object.entries(palette)){
    const sheet=document.createElement('canvas');sheet.width=atlas.width;sheet.height=atlas.height;const sc=sheet.getContext('2d');sc.drawImage(atlas,0,0);
    const pixels=sc.getImageData(0,0,sheet.width,sheet.height), d=pixels.data;
    const base=[221,62,38], baseAccent=[247,151,73], baseDark=[25,21,28];
    for(let i=0;i<d.length;i+=4){if(d[i]===base[0]&&d[i+1]===base[1]&&d[i+2]===base[2]){d[i]=pal.cloth[0];d[i+1]=pal.cloth[1];d[i+2]=pal.cloth[2]}else if(d[i]===baseAccent[0]&&d[i+1]===baseAccent[1]&&d[i+2]===baseAccent[2]){d[i]=pal.accent[0];d[i+1]=pal.accent[1];d[i+2]=pal.accent[2]}else if(d[i]===baseDark[0]&&d[i+1]===baseDark[1]&&d[i+2]===baseDark[2]){d[i]=pal.dark[0];d[i+1]=pal.dark[1];d[i+2]=pal.dark[2]}}
    sc.putImageData(pixels,0,0);fighterSheets[name]=sheet;
  }
  const poseIndex={idle:0,hp:1,lp:2,hk:3,lk:4,block:5,hit:6,special:1,run:0};
  function arena(){
    const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#141622');sky.addColorStop(.58,'#30303b');sky.addColorStop(.59,'#5a3d39');sky.addColorStop(1,'#17151b');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // distant moon and storm clouds
    const moon=ctx.createRadialGradient(481,105,6,481,105,85);moon.addColorStop(0,'#e5c4a4');moon.addColorStop(.72,'#b6857c');moon.addColorStop(1,'#8e6872');ctx.fillStyle=moon;ctx.beginPath();ctx.arc(481,105,75,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.35;ctx.fillStyle='#222331';for(let i=0;i<9;i++){ctx.beginPath();ctx.ellipse(i*142-25,70+(i%3)*22,95,21,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
    // jagged mountain silhouettes
    ctx.fillStyle='#1b1b27';ctx.beginPath();ctx.moveTo(0,245);for(let x=0;x<=W;x+=55)ctx.lineTo(x,205+Math.sin(x*.027)*35+(x%3)*8);ctx.lineTo(W,315);ctx.lineTo(0,315);ctx.fill();
    // fortress towers and red slit windows
    for(let i=0;i<8;i++){let x=i*142-20,h=90+(i%3)*32;ctx.fillStyle=i%2?'#24212a':'#211f29';ctx.fillRect(x,258-h,58,h+45);ctx.fillRect(x-8,254-h,74,9);ctx.fillStyle='#d75949';ctx.globalAlpha=.55;for(let j=0;j<3;j++)ctx.fillRect(x+12+j*15,279-h,4,20);ctx.globalAlpha=1}
    // ground plane and perspective
    ctx.fillStyle='#27232b';ctx.fillRect(0,314,W,H-314);ctx.strokeStyle='#554149';ctx.globalAlpha=.48;for(let x=-250;x<W+350;x+=90){ctx.beginPath();ctx.moveTo(480,316);ctx.lineTo(x,H);ctx.stroke()}for(let y=340;y<H;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.globalAlpha=1;
    // arena edge torches
    for(const x of [70,890]){ctx.fillStyle='#272129';ctx.fillRect(x-7,229,14,92);ctx.fillStyle='#5e3530';ctx.fillRect(x-12,237,24,8);ctx.fillStyle='#ff8b45';ctx.shadowColor='#ff6337';ctx.shadowBlur=22;ctx.beginPath();ctx.ellipse(x,219,8,18,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#ffcf79';ctx.beginPath();ctx.ellipse(x,220,3,10,0,0,Math.PI*2);ctx.fill()}
    // ground highlights
    ctx.fillStyle='#da7650';ctx.globalAlpha=.12;ctx.fillRect(0,314,W,3);ctx.globalAlpha=1;
  }
  function drawFighter(f){
    const frame=poseIndex[f.anim]??0, sheet=f.isPlayer?fighterSheets.player:fighterSheets.enemy;
    const x=Math.round(f.x), ground=314+f.y;
    ctx.save();ctx.translate(x,ground);if(f.facing<0)ctx.scale(-1,1);
    // shadow
    ctx.save();ctx.scale(1,.28);ctx.fillStyle='#07070b';ctx.globalAlpha=.56;ctx.beginPath();ctx.ellipse(0,0,37,12,0,0,Math.PI*2);ctx.fill();ctx.restore();
    if(f.flash>0&&Math.floor(f.flash/3)%2===0)ctx.globalAlpha=.48;
    ctx.drawImage(sheet,frame*80,0,80,112,-40,-112,80,112);
    // readable name tag
    ctx.restore();ctx.font='700 10px "Space Mono", monospace';ctx.textAlign='center';ctx.fillStyle=f.isPlayer?'#f18a60':'#70d5e5';ctx.fillText(f.isPlayer?'SCORPION':'SUB-ZERO',x,ground-119);
    if(f.freeze>0){ctx.strokeStyle='#93ecff';ctx.lineWidth=3;ctx.globalAlpha=.58;ctx.strokeRect(x-28,ground-100,56,94);ctx.globalAlpha=1}
  }
  function drawProjectile(p){ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=Math.max(.15,p.life/100);ctx.shadowBlur=18;ctx.shadowColor=p.color;if(p.type==='spear'){ctx.strokeStyle=p.color;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-22,0);ctx.lineTo(19,0);ctx.stroke();ctx.fillStyle='#eee';ctx.beginPath();ctx.moveTo(22,0);ctx.lineTo(11,-5);ctx.lineTo(11,5);ctx.fill()}else if(p.type==='ice'){ctx.fillStyle=p.color;ctx.beginPath();ctx.moveTo(0,-13);ctx.lineTo(9,0);ctx.lineTo(0,13);ctx.lineTo(-9,0);ctx.fill();ctx.strokeStyle='#ddfbff';ctx.stroke()}else if(p.type==='rocket'){ctx.fillStyle='#efa55a';ctx.fillRect(-17,-5,30,10);ctx.fillStyle='#f8e2a5';ctx.beginPath();ctx.moveTo(15,-7);ctx.lineTo(25,0);ctx.lineTo(15,7);ctx.fill();ctx.fillStyle='#f05634';ctx.fillRect(-24,-3,8,6)}else{ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffcf79';ctx.beginPath();ctx.arc(0,0,5,0,Math.PI*2);ctx.fill()}ctx.restore()}
  function draw(){ctx.save();if(state.shake>0){ctx.translate((Math.random()-.5)*state.shake,(Math.random()-.5)*state.shake)}arena();state.projectiles.forEach(drawProjectile);[player,enemy].sort((a,b)=>a.x-b.x).forEach(drawFighter);state.particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.life/25);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);ctx.globalAlpha=1});ctx.restore()}
  function setPose(f,name,duration=15){f.anim=name;f.animTime=duration}
  function spark(x,y,color='#ffc47d',n=9){for(let i=0;i<n;i++)state.particles.push({x,y,vx:(Math.random()-.5)*7,vy:(Math.random()-.7)*7,life:12+Math.random()*15,size:2+Math.random()*4,color})}
  function updateHud(){ui.playerHealth.style.width=Math.max(0,player.health)+'%';ui.enemyHealth.style.width=Math.max(0,enemy.health)+'%';ui.playerMeter.style.width=player.meter+'%';ui.enemyMeter.style.width=enemy.meter+'%';ui.timer.textContent=Math.max(0,Math.ceil(state.time)).toString().padStart(2,'0')}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.remove('active');void ui.toast.offsetWidth;ui.toast.classList.add('active')}
  function showBanner(title,sub){ui.title.textContent=title;ui.sub.textContent=sub;ui.banner.classList.remove('hidden');ui.banner.classList.remove('show');void ui.banner.offsetWidth;ui.banner.classList.add('show')}
  function hideBanner(){ui.banner.classList.add('hidden')}
  function hit(attacker,target,move){
    if(target.health<=0||target.stun>0)return;
    const blocking=target.block&&target.facing===Math.sign(attacker.x-target.x);
    const damage=blocking?Math.ceil(move.damage*.18):move.damage;
    target.health=Math.max(0,target.health-damage);target.meter=Math.min(100,target.meter+damage*1.1);attacker.meter=Math.min(100,attacker.meter+damage*.55);
    target.stun=blocking?6:move.stun;target.flash=blocking?3:12;target.x+=attacker.facing*(blocking?4:14);state.shake=blocking?3:7;
    spark(target.x+(attacker.facing*16),314-55,blocking?'#ffe5ac':(attacker.isPlayer?'#ff8b55':'#6be4fa'),blocking?4:12);
    if(!blocking&&attacker.isPlayer){state.combo++;state.comboUntil=1.1;if(state.combo>=2)toast(`${state.combo} HIT COMBO!`)}
    if(!blocking&&target.isPlayer)ui.flash.classList.add('active');
    updateHud();if(target.health<=0)endRound(attacker);
  }
  function attack(f,kind){if(!state.playing||state.roundOver||f.stun>0||f.attackCooldown>0||f.freeze>0)return;const target=f===player?enemy:player;const move=attacks[kind];f.attackCooldown=kind==='hp'||kind==='lp'?22:30;setPose(f,kind,14);if(Math.abs(target.x-f.x)<=move.range&&Math.abs(target.y-f.y)<55){hit(f,target,move)}else{f.attackWhiff=8}}
  function special(f,move){if(!state.playing||state.roundOver||f.stun>0||f.meter<18)return;f.meter=Math.max(0,f.meter-18);f.attackCooldown=33;setPose(f,'special',20);const target=f===player?enemy:player;let type='fire',color=f.isPlayer?'#ff7745':'#63d8ed',damage=13;
    if(move==='freeze'){type='ice';color='#80eaff';damage=12}else if(move==='spear'){type='spear';color=f.isPlayer?'#f0a94e':'#8de6ed';damage=14}else if(move==='rocket'){type='rocket';color='#ffb457';damage=16}
    const y=314-59+(f.crouch?16:0);state.projectiles.push({x:f.x+f.facing*35,y,vx:f.facing*(type==='rocket'?9:7),life:105,owner:f,type,color,damage});spark(f.x+f.facing*33,y,color,7);toast(({freeze:'ICE BLAST',spear:'SPEAR THROW',rocket:'ROCKET THROW',fire:'HELLFIRE'})[move]+'!');updateHud()}
  function endRound(winner){if(state.roundOver)return;state.roundOver=true;state.playing=false;winner.wins++;ui.pWins.textContent=player.wins;ui.eWins.textContent=enemy.wins;ui.status.textContent=winner.isPlayer?'SCORPION WINS':'SUB-ZERO WINS';showBanner(winner.isPlayer?'SCORPION WINS':'SUB-ZERO WINS',winner.isPlayer?'FLAWLESS VICTORY?':'FIGHT AGAIN');setTimeout(()=>{if(player.wins>=2||enemy.wins>=2){showBanner(player.wins>=2?'MATCH WON':'MATCH LOST','PRESS ↻ TO PLAY AGAIN')}else{nextRound()}},2200)}
  function nextRound(){state.round++;state.roundOver=false;player.health=100;enemy.health=100;player.meter=Math.min(player.meter+10,100);enemy.meter=Math.min(enemy.meter+10,100);player.x=275;enemy.x=685;player.stun=enemy.stun=0;state.time=99;state.projectiles=[];ui.status.textContent='FIGHT!';showBanner('ROUND '+(state.round===2?'TWO':'THREE'),'FIGHT!');setTimeout(()=>{hideBanner();state.playing=true},1300);updateHud()}
  function resetMatch(){player.wins=enemy.wins=0;ui.pWins.textContent=ui.eWins.textContent='0';state.round=1;state.roundOver=false;state.playing=false;state.time=99;state.projectiles=[];state.particles=[];player.health=enemy.health=100;player.meter=enemy.meter=22;player.x=275;enemy.x=685;player.stun=enemy.stun=0;ui.status.textContent='FIGHT!';updateHud();showBanner('ROUND ONE','READY YOURSELF');setTimeout(()=>{hideBanner();state.playing=true},1150)}
  function tryCommand(action){if(action==='run'){player.run=true;setTimeout(()=>player.run=false,300);return}if(action==='block'){player.block=true;player.crouch=false;setPose(player,'block',6);return}if(action==='special'){const seq=state.sequence.slice(-4).map(s=>s.key);if(seq.slice(-2).join(',')==='left,left')special(player,'spear');else if(seq.slice(-2).join(',')==='left,right')special(player,'freeze');else if(seq.slice(-2).join(',')==='down,right')special(player,'rocket');else if(seq.slice(-3).join(',')==='down,down-right,right')special(player,'fire');else special(player,'fire');return}if(attacks[action]){attack(player,action);record(action);return}if(action.startsWith('dir:')){const dir=action.slice(4);if(dir==='left'||dir==='right'||dir.includes('down'))record(dir);return}}
  function record(key){state.sequence.push({key,t:performance.now()});state.sequence=state.sequence.filter(s=>performance.now()-s.t<950).slice(-8)}
  function inputDir(dir,down){if(down){keys.add(dir);record(dir);if(dir==='left'){player.block=true;player.facing=-1}else if(dir==='right'){player.block=false;player.facing=1}else if(dir==='down'){player.crouch=true}else if(dir.includes('up')){if(player.jump===0){player.jump=1;player.airVy=-10}}}else{keys.delete(dir);if(dir==='left')player.block=false;if(dir==='down')player.crouch=false}}
  function keyboardDown(e){const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(keys.has(k))return;keys.add(k);const map={j:'hp',k:'lp',u:'hk',i:'lk',o:'special',shift:'run',' ':'block'};if(map[k])tryCommand(map[k]);if(k==='arrowleft'||k==='a')inputDir('left',true);if(k==='arrowright'||k==='d')inputDir('right',true);if(k==='arrowup'||k==='w')inputDir('up',true);if(k==='arrowdown'||k==='s')inputDir('down',true)}
  function keyboardUp(e){const k=e.key.toLowerCase();keys.delete(k);if(k==='arrowleft'||k==='a')inputDir('left',false);if(k==='arrowright'||k==='d')inputDir('right',false);if(k==='arrowup'||k==='w')inputDir('up',false);if(k==='arrowdown'||k==='s')inputDir('down',false);if(k===' ')player.block=false}

  function enemyAI(dt){if(!state.playing||state.roundOver||enemy.stun>0||enemy.freeze>0)return;enemy.aiWait-=dt*60;const dist=player.x-enemy.x;enemy.facing=dist<0?-1:1;enemy.block=Math.abs(dist)<110&&Math.random()<.018;
    if(Math.abs(dist)>175){enemy.x+=Math.sign(dist)*1.12*dt*60;enemy.anim='run'}else if(enemy.aiWait<=0){enemy.aiWait=22+Math.random()*38;const r=Math.random();if(player.attackCooldown>0&&r<.42){enemy.block=true;setPose(enemy,'block',18)}else if(r<.26){special(enemy,Math.random()<.5?'freeze':'spear')}else attack(enemy,['hp','lp','hk','lk'][Math.floor(Math.random()*4)])}
  }
  function update(dt){state.elapsed+=dt;state.shake=Math.max(0,state.shake-dt*18);if(state.comboUntil>0){state.comboUntil-=dt;if(state.comboUntil<=0)state.combo=0}
    if(state.playing&&!state.roundOver){state.time-=dt;if(state.time<=0){state.time=0;endRound(player.health>=enemy.health?player:enemy)}
      const speed=(player.run?3.5:2.1)*dt*60;if((keys.has('a')||keys.has('arrowleft'))&&!player.block)player.x-=speed;if((keys.has('d')||keys.has('arrowright'))&&!player.block)player.x+=speed;
      player.x=Math.max(45,Math.min(W-45,player.x));enemy.x=Math.max(45,Math.min(W-45,enemy.x));player.facing=enemy.x>player.x?1:-1;enemy.facing=player.x>enemy.x?1:-1;
      if(player.jump>0){player.y+=player.airVy;player.airVy+=.6;if(player.y>=0){player.y=0;player.jump=0;player.airVy=0;spark(player.x,313,'#d7c6b3',3)}}
      enemyAI(dt);
      for(const f of [player,enemy]){f.attackCooldown=Math.max(0,f.attackCooldown-dt*60);f.stun=Math.max(0,f.stun-dt*60);f.flash=Math.max(0,f.flash-dt*60);f.freeze=Math.max(0,f.freeze-dt*60);if(f.animTime>0){f.animTime-=dt*60;if(f.animTime<=0&&f.stun<=0)f.anim=f.block?'block':(f.crouch?'lp':'idle')}if(f.stun>0)f.anim='hit';else if(f.block)f.anim='block';else if(f.crouch&&f.animTime<=0)f.anim='lp';else if(!f.attackCooldown&&f.anim==='run')f.anim='idle'}
      for(let i=state.projectiles.length-1;i>=0;i--){const p=state.projectiles[i];p.x+=p.vx*dt*60;p.life-=dt*60;const target=p.owner===player?enemy:player;if(Math.abs(p.x-target.x)<27&&Math.abs(p.y-(314-56+target.y))<34){hit(p.owner,target,{damage:p.damage,stun:p.type==='ice'?60:22});if(p.type==='ice')target.freeze=55;spark(target.x,p.y,p.color,14);state.projectiles.splice(i,1);continue}if(p.life<=0||p.x<0||p.x>W)state.projectiles.splice(i,1)}
    }
    state.particles=state.particles.filter(p=>p.life>0);state.particles.forEach(p=>{p.x+=p.vx*dt*60;p.y+=p.vy*dt*60;p.vy+=.18;p.life-=dt*60});updateHud();
  }
  function loop(now){const dt=Math.min(.04,(now-state.last)/1000||0);state.last=now;update(dt);draw();requestAnimationFrame(loop)}
